import com.example.digitalhuman.model.ModelFactory;
import com.example.digitalhuman.model.StructuredModel;
import com.fasterxml.jackson.databind.ObjectMapper;

public final class V1Main {

    public static void main(String[] args) throws Exception {
        StructuredModel invoker = new PromptOnlyInvoker(ModelFactory.create());
        IntentParser parser = new Int
